// Protocol lookup data copied from read-only upstream Win32InputMode.ts.

fn lookup(code: &[u16], table: &[(&str, u16)]) -> Option<u16> {
    table
        .binary_search_by(|(name, _)| name.encode_utf16().cmp(code.iter().copied()))
        .ok()
        .map(|index| table[index].1)
}

pub(super) fn virtual_key(code: &[u16]) -> Option<u32> {
    lookup(code, VIRTUAL_KEYS).map(u32::from)
}

pub(super) fn scan_code(code: &[u16]) -> u16 {
    lookup(code, SCAN_CODES).unwrap_or(0)
}

pub(super) fn is_enhanced(code: &[u16]) -> bool {
    ENHANCED_KEYS
        .binary_search_by(|name| name.encode_utf16().cmp(code.iter().copied()))
        .is_ok()
}

